def movesToStamp(stamp: str, target: str) -> list[int]:
    S, T = len(stamp), len(target)
    target_list = list(target)
    moves = []
    stars = 0
    visited = [False] * (T - S + 1)
    def can_stamp(idx):
        changed = False
        for i in range(S):
            if target_list[idx + i] == '?': continue
            if target_list[idx + i] != stamp[i]: return False
            changed = True
        return changed
    while stars < T:
        stamped = False
        for i in range(T - S + 1):
            if not visited[i] and can_stamp(i):
                visited[i] = True
                stamped = True
                moves.append(i)
                for j in range(S):
                    if target_list[i + j] != '?':
                        target_list[i + j] = '?'
                        stars += 1
        if not stamped: return []
    return moves[::-1]

